import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOrbitron = makeLoadFont('Orbitron');
const loadRobotoMono = makeLoadFont('RobotoMono');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: orbitronFamily } = loadOrbitron();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();

// Precomputed starfield to ensure deterministic renders across parallel Lambda instances
const STARS_COUNT_MAX = 100;
const PRECOMPUTED_STARS = Array.from({ length: STARS_COUNT_MAX }).map((_, i) => {
  // Pure LCG/sin-based pseudo-random generator
  const seedX = Math.sin(i * 43758.5453) * 10000;
  const x = Math.round((seedX - Math.floor(seedX)) * 1920);

  const seedY = Math.sin(i * 76319.1234) * 10000;
  const y = Math.round((seedY - Math.floor(seedY)) * 800); // Kept in upper atmosphere

  const seedR = Math.sin(i * 12948.5912) * 10000;
  const r = 1 + Math.floor((seedR - Math.floor(seedR)) * 2.5); // Star size 1px to 3px

  const seedO = Math.sin(i * 98234.1824) * 10000;
  const maxOpacity = 0.15 + (seedO - Math.floor(seedO)) * 0.55; // Opacity 0.15 to 0.70

  const seedP = Math.sin(i * 28471.9312) * 10000;
  const pulsePhase = Math.floor((seedP - Math.floor(seedP)) * 100);

  return { x, y, r, maxOpacity, pulsePhase };
});



export type TechCollaborationProps = Record<string, any>;

const TechCollaboration: React.FC<TechCollaborationProps> = ({
  backgroundColor = "#05070f",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryColor = "#ffffff",
  glowColor = "#2BC4FF",
  showReflection = true,
  starsCount = 45,
  titleText = "COGNITIVE COLLABORATION MESH",
  subtitleText = "SYSTEM OVERVIEW // AGENT ORCHESTRATION ENGINE",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Safely extract background color logic
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation timeline timings (frames)
  // Frame 0-15: Ground line draws in
  // Frame 0-25: Main building outline draws in
  // Frame 8-28: Internal dividing walls draw in
  // Frame 15-35: Landscape trees draw in
  // Frame 32-62: AI agents pop in one-by-one with spring scale-up bounces
  // Frame 56-86: Collaboration connection lines draw themselves in

  const getDrawProgress = (start: number, end: number) => {
    return interpolate(frame, [start, end], [0, 1], {
      easing: Easing.bezier(0.25, 0.1, 0.25, 1),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
  };

  const getAgentScale = (startFrame: number) => {
    const relativeFrame = frame - startFrame;
    if (relativeFrame < 0) return 0;
    return spring({
      frame: relativeFrame,
      fps,
      config: {
        damping: 11,
        stiffness: 110,
        mass: 0.65,
      },
    });
  };

  const getLineProgress = (startFrame: number) => {
    return interpolate(frame, [startFrame, startFrame + 14], [0, 1], {
      easing: Easing.bezier(0.4, 0, 0.2, 1),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
  };

  // Starfield subtle organic pulse
  const getStarOpacity = (maxOpacity: number, phase: number) => {
    const pulse = Math.sin((frame + phase) * 0.07);
    return maxOpacity * (0.55 + 0.45 * pulse);
  };

  // Helper to render dual-layered glow stroke paths
  const renderGlowingPath = (
    d: string,
    progress: number,
    approxLength: number,
    coreWidth: number,
    glowWidth: number,
    id: string,
    isReflection: boolean
  ) => {
    const dashoffset = approxLength * (1 - progress);
    return (
      <g key={id}>
        {/* Glow Underlay (Omitted or simplified in reflection to ensure clean rendering performance) */}
        {!isReflection && (
          <path
            d={d}
            fill="none"
            stroke={glowColor}
            strokeWidth={glowWidth}
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeDasharray={`${approxLength}`}
            strokeDashoffset={dashoffset}
            filter="url(#cyan-glow)"
            opacity={0.75}
            style={{ transition: "none" }}
          />
        )}
        {/* Sharp Solid Core */}
        <path
          d={d}
          fill="none"
          stroke={primaryColor}
          strokeWidth={coreWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={`${approxLength}`}
          strokeDashoffset={dashoffset}
          opacity={isReflection ? 0.4 : 0.95}
          style={{ transition: "none" }}
        />
      </g>
    );
  };

  // Helper to render collaboration line & data packet animation
  const renderConnectingLine = (
    x1: number,
    y1: number,
    x2: number,
    y2: number,
    startFrame: number,
    id: string,
    isReflection: boolean
  ) => {
    const progress = getLineProgress(startFrame);
    if (progress <= 0) return null;

    const dx = x2 - x1;
    const dy = y2 - y1;
    const distance = Math.sqrt(dx * dx + dy * dy);

    // Repeated data package travel loop after the connection is fully built
    const packetTime = frame - (startFrame + 14);
    const packetActive = packetTime > 0;
    const packetProgress = packetActive ? (packetTime % 45) / 45 : 0;
    const px = x1 + dx * packetProgress;
    const py = y1 + dy * packetProgress;

    return (
      <g key={id}>
        {/* Glowing Network Line */}
        {!isReflection && (
          <line
            x1={x1}
            y1={y1}
            x2={x2}
            y2={y2}
            stroke={glowColor}
            strokeWidth="3.5"
            strokeOpacity={0.6 * progress}
            strokeDasharray={`${distance}`}
            strokeDashoffset={distance * (1 - progress)}
            filter="url(#cyan-glow)"
            style={{ transition: "none" }}
          />
        )}
        {/* Sharp core network line */}
        <line
          x1={x1}
          y1={y1}
          x2={x2}
          y2={y2}
          stroke={primaryColor}
          strokeWidth="1.5"
          strokeOpacity={isReflection ? 0.25 : 0.85 * progress}
          strokeDasharray={`${distance}`}
          strokeDashoffset={distance * (1 - progress)}
          style={{ transition: "none" }}
        />
        {/* Traveling data packets */}
        {packetActive && !isReflection && (
          <circle
            cx={px}
            cy={py}
            r="4.5"
            fill={primaryColor}
            filter="url(#cyan-glow)"
            style={{ transition: "none" }}
          />
        )}
      </g>
    );
  };

  // Helper to render stylized AI Agent Robot Head
  const renderAgent = (
    cx: number,
    cy: number,
    scale: number,
    isReflection: boolean
  ) => {
    if (scale <= 0) return null;

    const dotPulse = Math.sin(frame * 0.16) * 0.5 + 0.5; // Smooth loop 0 to 1
    const dotScale = 1 + dotPulse * 0.45;
    const dotOpacity = 0.55 + (1 - dotPulse) * 0.45;

    return (
      <g
        transform={`translate(${cx}, ${cy}) scale(${scale})`}
        style={{ transformOrigin: "center", transition: "none" }}
      >
        {/* Neon Glow backdrop behind head (omitted in reflection for rendering efficiency) */}
        {!isReflection && (
          <g filter="url(#cyan-glow)" opacity={0.65} style={{ transition: "none" }}>
            <rect x="-55" y="-40" width="110" height="80" rx="28" fill="none" stroke={glowColor} strokeWidth="5" />
            <rect x="-67" y="-20" width="12" height="40" rx="6" fill="none" stroke={glowColor} strokeWidth="4" />
            <rect x="55" y="-20" width="12" height="40" rx="6" fill="none" stroke={glowColor} strokeWidth="4" />
            <line x1="0" y1="-40" x2="0" y2="-60" stroke={glowColor} strokeWidth="4" />
            <circle cx="0" cy="-65" r="7" fill="none" stroke={glowColor} strokeWidth="4" />
          </g>
        )}

        {/* Clean Line-Art robot head elements */}
        <rect
          x="-55"
          y="-40"
          width="110"
          height="80"
          rx="28"
          fill={backgroundColor}
          stroke={primaryColor}
          strokeWidth="3.5"
        />
        <rect
          x="-67"
          y="-20"
          width="12"
          height="40"
          rx="6"
          fill={backgroundColor}
          stroke={primaryColor}
          strokeWidth="2.5"
        />
        <rect
          x="55"
          y="-20"
          width="12"
          height="40"
          rx="6"
          fill={backgroundColor}
          stroke={primaryColor}
          strokeWidth="2.5"
        />

        {/* Dynamic vertical glowing eyes */}
        <rect x="-24" y="-12" width="10" height="24" rx="5" fill={primaryColor} />
        <rect x="14" y="-12" width="10" height="24" rx="5" fill={primaryColor} />

        {/* Top Antenna */}
        <line x1="0" y1="-40" x2="0" y2="-60" stroke={primaryColor} strokeWidth="3" />
        <circle cx="0" cy="-65" r="7" fill={backgroundColor} stroke={primaryColor} strokeWidth="2.5" />

        {/* Top-Right Activity Pulse Dot */}
        <g transform="translate(68, -45)" style={{ transition: "none" }}>
          {!isReflection && (
            <circle
              cx="0"
              cy="0"
              r={9 * dotScale}
              fill={glowColor}
              opacity={0.45 * dotOpacity}
              filter="url(#cyan-glow)"
              style={{ transition: "none" }}
            />
          )}
          <circle cx="0" cy="0" r="5" fill={primaryColor} style={{ transition: "none" }} />
        </g>
      </g>
    );
  };

  // Consolidated render pass for the whole central scene (supports true mirrored duplication)
  const renderScene = (isReflection: boolean) => {
    const groundProg = getDrawProgress(0, 15);
    const outlineProg = getDrawProgress(0, 25);
    const dividersProg = getDrawProgress(8, 28);
    const treesProg = getDrawProgress(15, 35);

    const scale1 = getAgentScale(32);
    const scale2 = getAgentScale(38);
    const scale3 = getAgentScale(44);
    const scale4 = getAgentScale(50);

    return (
      <g>
        {/* Ground Floor Support Base */}
        {renderGlowingPath("M 100 850 L 1820 850", groundProg, 1720, 2.5, 6, "ground", isReflection)}

        {/* Modern Corporate/Office Building Frame */}
        {renderGlowingPath(
          "M 560 850 L 590 850 Q 610 850 610 830 L 610 250 L 785 250 L 785 150 L 1135 150 L 1135 250 L 1310 250 L 1310 830 Q 1310 850 1330 850 L 1360 850",
          outlineProg,
          2500,
          3.5,
          9,
          "building-outline",
          isReflection
        )}

        {/* Horizontal Floor Separator (Divider 1) */}
        {renderGlowingPath("M 610 510 L 1310 510", dividersProg, 700, 2.5, 6, "div1", isReflection)}

        {/* Vertical Upper Wall Separator (Divider 2) */}
        {renderGlowingPath("M 960 250 L 960 510", dividersProg, 260, 2.5, 6, "div2", isReflection)}

        {/* Vertical Central Column to Door (Divider 3) */}
        {renderGlowingPath("M 960 510 L 960 710", dividersProg, 200, 2.5, 6, "div3", isReflection)}

        {/* Double Entrance Door Outline (Divider 4) */}
        {renderGlowingPath(
          "M 880 850 L 880 710 L 960 710 L 1040 710 L 1040 850",
          dividersProg,
          440,
          2.5,
          6,
          "div4",
          isReflection
        )}

        {/* Double Door Middle Split (Divider 5) */}
        {renderGlowingPath("M 960 710 L 960 850", dividersProg, 140, 2.5, 6, "div5", isReflection)}

        {/* Left Hand Symmetrical Tree */}
        {renderGlowingPath(
          "M 500 850 L 500 780 M 500 780 C 470 780, 460 730, 500 680 C 540 730, 530 780, 500 780",
          treesProg,
          400,
          2.5,
          6,
          "tree-left",
          isReflection
        )}

        {/* Right Hand Symmetrical Tree */}
        {renderGlowingPath(
          "M 1420 850 L 1420 780 M 1420 780 C 1390 780, 1380 730, 1420 680 C 1460 730, 1450 780, 1420 780",
          treesProg,
          400,
          2.5,
          6,
          "tree-right",
          isReflection
        )}

        {/* Dynamic mesh collaboration cables */}
        {renderConnectingLine(785, 380, 1135, 380, 56, "conn1", isReflection)} {/* Horiz Upper */}
        {renderConnectingLine(785, 630, 1135, 630, 62, "conn2", isReflection)} {/* Horiz Lower */}
        {renderConnectingLine(785, 380, 1135, 630, 68, "conn3", isReflection)} {/* Diagonal Left to Right */}
        {renderConnectingLine(785, 630, 1135, 380, 74, "conn4", isReflection)} {/* Diagonal Right to Left */}

        {/* AI Agents (Robot Heads) inside each quadrant */}
        {renderAgent(785, 380, scale1, isReflection)}  {/* Quadrant 1: Top-Left */}
        {renderAgent(1135, 380, scale2, isReflection)} {/* Quadrant 2: Top-Right */}
        {renderAgent(785, 630, scale3, isReflection)}  {/* Quadrant 3: Bottom-Left */}
        {renderAgent(1135, 630, scale4, isReflection)} {/* Quadrant 4: Bottom-Right */}
      </g>
    );
  };

  // Tech HUD display entrance fade
  const hudProgress = interpolate(frame, [15, 45], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  const starsToRender = PRECOMPUTED_STARS.slice(0, starsCount);

  // Styled overlay states
  const overlayTitleStyle: React.CSSProperties = {
    position: "absolute",
    top: "8%",
    left: "5%",
    color: primaryColor,
    fontFamily: orbitronFamily,
    opacity: hudProgress,
    transform: `translateY(${interpolate(hudProgress, [0, 1], [15, 0])}px)`,
    transition: "none",
    pointerEvents: "none",
  };

  const overlaySubtitleStyle: React.CSSProperties = {
    fontFamily: robotoMonoFamily,
    fontSize: "14px",
    color: glowColor,
    letterSpacing: "2.5px",
    marginTop: "8px",
    opacity: 0.85,
    textShadow: `0 0 10px ${glowColor}66`,
  };

  const hudStatusBoxStyle: React.CSSProperties = {
    position: "absolute",
    bottom: "26%", // Safe boundary above glossy floor level (y=850)
    right: "5%",
    color: primaryColor,
    fontFamily: robotoMonoFamily,
    fontSize: "13px",
    opacity: hudProgress,
    transform: `translateY(${interpolate(hudProgress, [0, 1], [15, 0])}px)`,
    textAlign: "right",
    transition: "none",
    pointerEvents: "none",
    letterSpacing: "1.2px",
    lineHeight: "1.8",
  };

  const statusDotStyle: React.CSSProperties = {
    display: "inline-block",
    width: "8px",
    height: "8px",
    borderRadius: "50%",
    backgroundColor: "#10b981",
    marginLeft: "8px",
    boxShadow: "0 0 8px #10b981",
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Absolute responsive SVG Canvas containing all structural elements */}
      <svg
        viewBox="0 0 1920 1080"
        width="100%"
        height="100%"
        style={{ position: "absolute", left: 0, top: 0 }}
      >
        <defs>
          {/* Cybernetic drop shadow bloom neon glow filter */}
          <filter id="cyan-glow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur in="SourceGraphic" stdDeviation="5" result="blur1" />
            <feGaussianBlur in="SourceGraphic" stdDeviation="11" result="blur2" />
            <feMerge>
              <feMergeNode in="blur2" />
              <feMergeNode in="blur1" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>

          {/* Glossy Floor Reflection Vertical Fade Gradient */}
          <linearGradient
            id="reflection-fade"
            x1="0"
            y1="850"
            x2="0"
            y2="1080"
            gradientUnits="userSpaceOnUse"
          >
            <stop offset="0%" stopColor="white" stopOpacity="0.45" />
            <stop offset="70%" stopColor="white" stopOpacity="0.10" />
            <stop offset="100%" stopColor="white" stopOpacity="0.0" />
          </linearGradient>

          {/* Mask matching the floor gradient structure */}
          <mask id="reflection-mask">
            <rect x="0" y="850" width="1920" height="230" fill="url(#reflection-fade)" />
          </mask>
        </defs>

        {/* Space background subtle ambient glow */}
        <circle
          cx="960"
          cy="500"
          r="450"
          fill={glowColor}
          opacity="0.035"
          filter="url(#cyan-glow)"
          style={{ transition: "none" }}
        />

        {/* Sparkly Starfield */}
        {starsToRender.map((star, idx) => {
          const op = getStarOpacity(star.maxOpacity, star.pulsePhase);
          return (
            <circle
              key={idx}
              cx={star.x}
              cy={star.y}
              r={star.r}
              fill={primaryColor}
              opacity={op}
              style={{ transition: "none" }}
            />
          );
        })}

        {/* Primary View Elements */}
        {renderScene(false)}

        {/* Glossy Reflective Floor (Vertically Flipped and Masked) */}
        {showReflection && (
          <g
            transform="translate(0, 1700) scale(1, -1)"
            mask="url(#reflection-mask)"
          >
            {renderScene(true)}
          </g>
        )}
      </svg>

      {/* Cybernetic Tech HUD Overlays */}
      <div style={overlayTitleStyle}>
        <div style={{ fontSize: "28px", fontWeight: "bold", letterSpacing: "3px" }}>
          {titleText}
        </div>
        <div style={overlaySubtitleStyle}>{subtitleText}</div>
      </div>

      <div style={hudStatusBoxStyle}>
        <div>
          STATUS: <span style={{ color: "#10b981", fontWeight: "bold" }}>ACTIVE</span>
          <span style={statusDotStyle} />
        </div>
        <div>MESH NODES: 4 // SECURE</div>
        <div>SYS_LATENCY: 14MS</div>
      </div>
    </AbsoluteFill>
  );
};

export default TechCollaboration;